-- Whether the provider of an imported event gives its start time (ADR-006, decision 5). An ArtWizard exhibition run
-- without opening hours starts at a default 12:00 in Europe/Kyiv, which only orders the event and its sessions; this
-- column says that the time is a default. Organization events always have a start time, hence the default. No event
-- stored so far has a default start, so nothing is backfilled. nearby_import's table grants on events cover the column.
ALTER TABLE "events"
    ADD COLUMN "start_time_known" BOOLEAN NOT NULL DEFAULT true;
